namespace RecipeSharingApp.Models;

public class Category
{
    public string Slug { get; set; } = "";
    public string Name { get; set; } = "";
    public string Icon { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string CategorySlug { get; set; } = "";
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings == 0 ? 0 : (double)RatingSum / TotalRatings;
}

public class RecipeSubmission
{
    public required string Title { get; set; }
    public required string Ingredients { get; set; }
    public required string Steps { get; set; }
    public required string CategorySlug { get; set; }
}

using RecipeSharingApp.Models;

namespace RecipeSharingApp.Services;

public class RecipeService
{
    private readonly List<Category> _categories =
    [
        new() { Slug = "appetizers", Name = "Appetizers", Icon = "🥗", Description = "Small bites to start your meal" },
        new() { Slug = "main-courses", Name = "Main Courses", Icon = "🍖", Description = "Hearty dishes for the center of the table" },
        new() { Slug = "desserts", Name = "Desserts", Icon = "🍰", Description = "Sweet treats to finish your meal" },
        new() { Slug = "beverages", Name = "Beverages", Icon = "🥤", Description = "Refreshing drinks for any occasion" },
    ];

    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Bruschetta", CategorySlug = "appetizers",
            Ingredients = ["4 slices crusty bread", "2 tomatoes, diced", "Fresh basil", "Olive oil", "Garlic clove"],
            Steps = ["Toast bread slices until golden.", "Rub garlic on warm bread.", "Top with diced tomatoes and basil.", "Drizzle with olive oil and serve."],
            TotalRatings = 12, RatingSum = 50
        },
        new()
        {
            Id = 2, Title = "Stuffed Mushrooms", CategorySlug = "appetizers",
            Ingredients = ["12 button mushrooms", "Cream cheese", "Garlic", "Parmesan", "Breadcrumbs"],
            Steps = ["Remove stems from mushrooms.", "Mix cream cheese, garlic, and parmesan.", "Fill mushroom caps with mixture.", "Top with breadcrumbs and bake at 375°F for 20 min."],
            TotalRatings = 8, RatingSum = 35
        },
        new()
        {
            Id = 3, Title = "Grilled Chicken Parmesan", CategorySlug = "main-courses",
            Ingredients = ["2 chicken breasts", "Marinara sauce", "Mozzarella", "Parmesan", "Italian seasoning"],
            Steps = ["Season chicken with Italian seasoning.", "Grill until cooked through.", "Top with marinara and mozzarella.", "Broil until cheese melts."],
            TotalRatings = 20, RatingSum = 88
        },
        new()
        {
            Id = 4, Title = "Beef Stir Fry", CategorySlug = "main-courses",
            Ingredients = ["1 lb beef strips", "Bell peppers", "Soy sauce", "Ginger", "Rice"],
            Steps = ["Cook rice according to package.", "Stir-fry beef until browned.", "Add peppers, ginger, and soy sauce.", "Serve over rice."],
            TotalRatings = 15, RatingSum = 62
        },
        new()
        {
            Id = 5, Title = "Chocolate Lava Cake", CategorySlug = "desserts",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour"],
            Steps = ["Melt chocolate and butter together.", "Whisk eggs and sugar, fold in chocolate.", "Add flour and pour into ramekins.", "Bake at 425°F for 12 minutes."],
            TotalRatings = 25, RatingSum = 118
        },
        new()
        {
            Id = 6, Title = "Mango Smoothie", CategorySlug = "beverages",
            Ingredients = ["1 mango", "1 cup yogurt", "½ cup milk", "Honey", "Ice cubes"],
            Steps = ["Peel and chop the mango.", "Blend all ingredients until smooth.", "Pour into a glass and serve cold."],
            TotalRatings = 10, RatingSum = 43
        },
    ];

    private int _nextId = 7;

    public List<Category> GetCategories() => _categories;

    public Category? GetCategory(string slug) =>
        _categories.FirstOrDefault(c => c.Slug == slug);

    public List<Recipe> GetRecipesByCategory(string categorySlug) =>
        _recipes.Where(r => r.CategorySlug == categorySlug).ToList();

    public Recipe? GetRecipe(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipe(recipeId);
        if (recipe is null || stars is < 1 or > 5) return;
        recipe.TotalRatings++;
        recipe.RatingSum += stars;
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            CategorySlug = submission.CategorySlug,
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

