@page "/categories"
@using RecipeSharingApp.Services
@inject RecipeService RecipeService

<PageTitle>Browse Categories</PageTitle>

<h1>Browse by Category</h1>

<div class="grid">
    @foreach (var cat in RecipeService.GetCategories())
    {
        <a href="/categories/@cat.Slug" class="card category-card">
            <span class="card-icon">@cat.Icon</span>
            <h3>@cat.Name</h3>
            <p>@cat.Description</p>
        </a>
    }
</div>

@page "/categories/{Slug}"
@using RecipeSharingApp.Services
@using RecipeSharingApp.Models
@inject RecipeService RecipeService

<PageTitle>@(category?.Name ?? "Category") - RecipeShare</PageTitle>

@if (category is null)
{
    <h1>Category not found</h1>
    <p><a href="/categories">Back to categories</a></p>
}
else
{
    <h1>@category.Icon @category.Name</h1>
    <p>@category.Description</p>

    <div class="grid">
        @foreach (var recipe in recipes)
        {
            <a href="/recipe/@recipe.Id" class="card recipe-card">
                <h3>@recipe.Title</h3>
                <p class="recipe-meta">
                    @if (recipe.TotalRatings > 0)
                    {
                        <span class="stars">@GetStars(recipe.AverageRating)</span>
                        <span>(@recipe.TotalRatings ratings)</span>
                    }
                    else
                    {
                        <span>No ratings yet</span>
                    }
                </p>
                <p>@recipe.Ingredients.Count ingredients · @recipe.Steps.Count steps</p>
            </a>
        }
    </div>

    @if (recipes.Count == 0)
    {
        <p class="empty-state">No recipes in this category yet. <a href="/submit">Be the first to submit one!</a></p>
    }
}

@code {
    [Parameter] public string Slug { get; set; } = "";
    private Category? category;
    private List<Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        category = RecipeService.GetCategory(Slug);
        recipes = category is not null ? RecipeService.GetRecipesByCategory(Slug) : [];
    }

    private static string GetStars(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@page "/recipe/{Id:int}"
@using RecipeSharingApp.Services
@using RecipeSharingApp.Models
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (recipe is null)
{
    <h1>Recipe not found</h1>
    <p><a href="/categories">Browse categories</a></p>
}
else
{
    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo;
        <a href="/categories">Categories</a> &rsaquo;
        <a href="/categories/@recipe.CategorySlug">@(category?.Name ?? recipe.CategorySlug)</a> &rsaquo;
        <span>@recipe.Title</span>
    </nav>

    <article class="recipe-detail">
        <h1>@recipe.Title</h1>

        <StarRating RecipeId="recipe.Id"
                    CurrentAverage="recipe.AverageRating"
                    TotalRatings="recipe.TotalRatings" />

        <section class="recipe-section">
            <h2>Ingredients</h2>
            <ul>
                @foreach (var ingredient in recipe.Ingredients)
                {
                    <li>@ingredient</li>
                }
            </ul>
        </section>

        <section class="recipe-section">
            <h2>Steps</h2>
            <ol>
                @foreach (var step in recipe.Steps)
                {
                    <li>@step</li>
                }
            </ol>
        </section>
    </article>
}

@code {
    [Parameter] public int Id { get; set; }
    private Recipe? recipe;
    private Category? category;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipe(Id);
        if (recipe is not null)
            category = RecipeService.GetCategory(recipe.CategorySlug);
    }
}

@page "/submit"
@using RecipeSharingApp.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>

@if (submitted)
{
    <div class="success-message">
        <h2>✅ Recipe submitted!</h2>
        <p>Your recipe "<strong>@title</strong>" has been added.</p>
        <a href="/recipe/@submittedId" class="btn btn-primary">View Recipe</a>
    </div>
}
else
{
    <form @onsubmit="HandleSubmit" class="recipe-form">
        <div class="form-group">
            <label for="title">Recipe Title</label>
            <input id="title" @bind="title" required placeholder="e.g. Grandma's Apple Pie" />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <select id="category" @bind="categorySlug" required>
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat.Slug">@cat.Icon @cat.Name</option>
                }
            </select>
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients (one per line)</label>
            <textarea id="ingredients" @bind="ingredients" rows="6" required
                      placeholder="2 cups flour&#10;1 cup sugar&#10;3 apples, sliced"></textarea>
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <textarea id="steps" @bind="steps" rows="6" required
                      placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add apples and bake."></textarea>
        </div>

        <button type="submit" class="btn btn-primary" disabled="@(!IsValid)">Submit Recipe</button>
    </form>
}

@code {
    private string title = "";
    private string categorySlug = "";
    private string ingredients = "";
    private string steps = "";
    private bool submitted;
    private int submittedId;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(title) &&
        !string.IsNullOrWhiteSpace(categorySlug) &&
        !string.IsNullOrWhiteSpace(ingredients) &&
        !string.IsNullOrWhiteSpace(steps);

    private void HandleSubmit()
    {
        if (!IsValid) return;

        var recipe = RecipeService.AddRecipe(new Models.RecipeSubmission
        {
            Title = title,
            CategorySlug = categorySlug,
            Ingredients = ingredients,
            Steps = steps
        });

        submittedId = recipe.Id;
        submitted = true;
    }
}

@rendermode InteractiveServer
@using RecipeSharingApp.Services
@inject RecipeService RecipeService

<div class="star-rating">
    <div class="stars-interactive">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= (hovered > 0 ? hovered : userRating) ? "filled" : "")"
                  @onclick="() => Rate(star)"
                  @onmouseover="() => hovered = star"
                  @onmouseout="() => hovered = 0"
                  role="button"
                  aria-label="Rate @star stars">★</span>
        }
    </div>
    @if (hasRated)
    {
        <p class="rating-thanks">Thanks! You rated this @userRating/5.</p>
    }
    else
    {
        <p class="rating-prompt">Click to rate this recipe</p>
    }
    <p class="rating-summary">
        Average: @CurrentAverage.ToString("0.0") / 5
        (@TotalRatings @(TotalRatings == 1 ? "rating" : "ratings"))
    </p>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentAverage { get; set; }
    [Parameter] public int TotalRatings { get; set; }

    private int hovered;
    private int userRating;
    private bool hasRated;

    private void Rate(int stars)
    {
        if (hasRated) return;
        userRating = stars;
        hasRated = true;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetRecipe(RecipeId);
        if (recipe is not null)
        {
            CurrentAverage = recipe.AverageRating;
            TotalRatings = recipe.TotalRatings;
        }
    }
}

