@code {
    private string title = "";
    private string categorySlug = "";
    private string ingredients = "";
    private string steps = "";
    private bool submitted;
    private int submittedId;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(title) &&
        !string.IsNullOrWhiteSpace(categorySlug) &&
        !string.IsNullOrWhiteSpace(ingredients) &&
        !string.IsNullOrWhiteSpace(steps);

    private void HandleSubmit()
    {
        if (!IsValid) return;

        var recipe = RecipeService.AddRecipe(new Models.RecipeSubmission
        {
            Title = title,
            CategorySlug = categorySlug,
            Ingredients = ingredients,
            Steps = steps
        });

        submittedId = recipe.Id;
        submitted = true;
    }
}

@rendermode InteractiveServer
@using RecipeSharingApp.Services
@inject RecipeService RecipeService

<div class="star-rating">
    <div class="stars-interactive">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= (hovered > 0 ? hovered : userRating) ? "filled" : "")"
                  @onclick="() => Rate(star)"
                  @onmouseover="() => hovered = star"
                  @onmouseout="() => hovered = 0"
                  role="button"
                  aria-label="Rate @star stars">★</span>
        }
    </div>
    @if (hasRated)
    {
        <p class="rating-thanks">Thanks! You rated this @userRating/5.</p>
    }
    else
    {
        <p class="rating-prompt">Click to rate this recipe</p>
    }
    <p class="rating-summary">
        Average: @CurrentAverage.ToString("0.0") / 5
        (@TotalRatings @(TotalRatings == 1 ? "rating" : "ratings"))
    </p>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentAverage { get; set; }
    [Parameter] public int TotalRatings { get; set; }

    private int hovered;
    private int userRating;
    private bool hasRated;

    private void Rate(int stars)
    {
        if (hasRated) return;
        userRating = stars;
        hasRated = true;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetRecipe(RecipeId);
        if (recipe is not null)
        {
            CurrentAverage = recipe.AverageRating;
            TotalRatings = recipe.TotalRatings;
        }
    }
}

