toolArgs.new_str:
html, body {
    margin: 0;
    padding: 0;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a1a2e;
    background: #fafafa;
}

a { color: #e94560; text-decoration: none; }
a:hover { text-decoration: underline; }

/* Nav */
.site-header { background: #1a1a2e; color: white; }
.nav-bar {
    max-width: 960px; margin: 0 auto; padding: 1rem;
    display: flex; align-items: center; justify-content: space-between;
}
.brand { font-size: 1.4rem; font-weight: bold; color: white !important; }
.brand:hover { text-decoration: none; }
.nav-links a { color: #eee; margin-left: 1.5rem; }
.nav-links a:hover { color: #e94560; text-decoration: none; }

/* Page content */
.page-content { max-width: 960px; margin: 0 auto; padding: 2rem 1rem; }

/* Footer */
.site-footer { text-align: center; padding: 2rem 1rem; color: #888; border-top: 1px solid #eee; }

/* Hero */
.hero { text-align: center; padding: 3rem 1rem; }
.hero h1 { font-size: 2.2rem; margin-bottom: 0.5rem; }
.hero p { font-size: 1.1rem; color: #555; margin-bottom: 1.5rem; }

/* Buttons */
.btn {
    display: inline-block; padding: 0.7rem 1.5rem; border-radius: 6px;
    border: none; cursor: pointer; font-size: 1rem; text-decoration: none;
}
.btn-primary { background: #e94560; color: white; }
.btn-primary:hover { background: #c73a54; text-decoration: none; }
.btn:disabled { opacity: 0.5; cursor: not-allowed; }

/* Grid */
.grid {
    display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.5rem; margin-top: 1.5rem;
}

/* Cards */
.card {
    background: white; border-radius: 10px; padding: 1.5rem;
    box-shadow: 0 2px 8px rgba(0,0,0,0.08); transition: transform 0.15s, box-shadow 0.15s;
    display: block; color: inherit;
}
.card:hover { transform: translateY(-3px); box-shadow: 0 4px 16px rgba(0,0,0,0.12); text-decoration: none; }
.card h3 { margin: 0.5rem 0; }
.card p { color: #666; margin: 0.3rem 0; font-size: 0.95rem; }
.card-icon { font-size: 2.5rem; }

/* Recipe meta */
.stars { color: #f5a623; letter-spacing: 2px; }
.recipe-meta { font-size: 0.9rem; }

/* Breadcrumb */
.breadcrumb { font-size: 0.9rem; margin-bottom: 1.5rem; color: #888; }
.breadcrumb a { color: #e94560; }

/* Recipe detail */
.recipe-detail h1 { margin-bottom: 0.5rem; }
.recipe-section { margin-top: 2rem; }
.recipe-section h2 { border-bottom: 2px solid #e94560; display: inline-block; padding-bottom: 4px; }
.recipe-section ul, .recipe-section ol { padding-left: 1.5rem; line-height: 1.8; }

/* Star rating widget */
.star-rating { margin: 1rem 0; padding: 1rem; background: #fff8f0; border-radius: 8px; }
.stars-interactive { font-size: 2rem; letter-spacing: 4px; }
.star { color: #ddd; cursor: pointer; transition: color 0.1s; }
.star.filled { color: #f5a623; }
.star:hover { color: #f5a623; }
.rating-thanks { color: #27ae60; font-weight: 500; }
.rating-prompt { color: #888; font-size: 0.9rem; }
.rating-summary { color: #555; font-size: 0.9rem; }

/* Form */
.recipe-form { max-width: 600px; }
.form-group { margin-bottom: 1.5rem; }
.form-group label { display: block; font-weight: 600; margin-bottom: 0.4rem; }
.form-group input, .form-group select, .form-group textarea {
    width: 100%; padding: 0.6rem; border: 1px solid #ccc; border-radius: 6px;
    font-size: 1rem; box-sizing: border-box;
}
.form-group input:focus, .form-group select:focus, .form-group textarea:focus {
    outline: none; border-color: #e94560; box-shadow: 0 0 0 3px rgba(233,69,96,0.15);
}

/* Success */
.success-message { background: #e8f8f0; padding: 2rem; border-radius: 10px; text-align: center; }

/* Empty state */
.empty-state { text-align: center; color: #888; padding: 2rem; }

/* Categories section on home */
.categories-grid { margin-top: 2rem; }
.categories-grid h2 { text-align: center; }

h1:focus {
    outline: none;
}

.valid.modified:not([type=checkbox]) {
    outline: 1px solid #26b050;
}

.invalid {
    outline: 1px solid #e50000;
}

.validation-message {
    color: #e50000;
}

